import json
import pandas as pd

FIELD_MAP = {
    "user_id": "user_id", "id": "user_id", "userId": "user_id",
    "email": "email", "email_address": "email",
    "full_name": "name", "name": "name", "userName": "name",
    "registration_date": "created_date", "created_at": "created_date", "joined": "created_date",
    "status": "status",
}
ACTIVE_FIELDS = ("is_active", "active")
FIELDS = ["name", "email", "created_date", "status"]


def norm_date(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    try:
        return pd.to_datetime(str(v)).strftime("%Y-%m-%d")
    except Exception:
        return str(v)


def to_bool(v):
    if isinstance(v, str):
        return v.strip().lower() in ("true", "1", "yes", "y", "t")
    return bool(v)


def normalize(records):
    out = {}
    for r in records:
        rec = {}
        for k, v in r.items():
            if k in FIELD_MAP:
                rec[FIELD_MAP[k]] = v
            elif k in ACTIVE_FIELDS and "status" not in r:
                if v is not None and not (isinstance(v, float) and pd.isna(v)):
                    rec["status"] = "active" if to_bool(v) else "inactive"
        if rec.get("user_id") is None:
            continue
        rec["user_id"] = int(rec["user_id"])
        if "created_date" in rec:
            rec["created_date"] = norm_date(rec["created_date"])
        for f in ("name", "email", "status"):
            if rec.get(f) is not None and not (isinstance(rec[f], float) and pd.isna(rec[f])):
                rec[f] = str(rec[f])
            else:
                rec.pop(f, None)
        out[rec["user_id"]] = rec
    return out


with open("/data/source_a/users.json") as fh:
    a = json.load(fh)
b = pd.read_csv("/data/source_b/users.csv", dtype=str, keep_default_na=False).to_dict("records")
c = pd.read_parquet("/data/source_c/users.parquet").to_dict("records")

sources = {"source_a": normalize(a), "source_b": normalize(b), "source_c": normalize(c)}
priority = ["source_a", "source_b", "source_c"]

all_ids = sorted(set().union(*[set(s) for s in sources.values()]))
rows, conflicts = [], []
for uid in all_ids:
    row = {"user_id": uid}
    for f in FIELDS:
        vals = {s: sources[s][uid][f] for s in priority if uid in sources[s] and sources[s][uid].get(f) is not None}
        selected = vals[next(s for s in priority if s in vals)] if vals else None
        row[f] = selected
        if len(set(vals.values())) > 1:
            conflicts.append({"user_id": uid, "field": f, "values": vals, "selected": selected})
    rows.append(row)

df = pd.DataFrame(rows, columns=["user_id", "name", "email", "created_date", "status"])
df["user_id"] = df["user_id"].astype("int64")
for col in ["name", "email", "created_date", "status"]:
    df[col] = df[col].astype(object)
df.to_parquet("/app/merged_users.parquet", index=False)

with open("/app/conflicts.json", "w") as fh:
    json.dump({"total_conflicts": len(conflicts), "conflicts": conflicts}, fh, indent=2)
print(df.to_string()); print(json.dumps(conflicts, indent=1))
EOF
./envcp ./merge.py :/app/merge.py && ./envrun 'cd /app && python3 merge.py && python3 -c "import pyarrow.parquet as pq; print(pq.read_schema(\"/app/merged_users.parquet\"))"'
